package synth

import kotlin.properties.Delegates

fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

class Counter230 {
    var current: Int by Delegates.observable(13) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
sealed class Outcome231 {
    data class Success(val payload: String) : Outcome231()
    data object Failure : Outcome231()
}

fun describe231(outcome: Outcome231): String = when (outcome) {
    is Outcome231.Success -> outcome.payload
    Outcome231.Failure -> "failed"
}
fun <T, R> List<T>.mapChecked232(transform: (T) -> R): List<R> {
    val result = mutableListOf<R>()
    for (item in this) {
        result.add(transform(item))
    }
    return result
}
